        '{"blocks":[{"key":"hero","title":"Hero","fields":{"eyebrow":"Partnerství","h1":"Partnerství, která posilují profesní vzdělávání","lead":"Spolupracujeme s organizacemi a experty, kteří vytvářejí smysluplné programy a odpovědně přistupují k výsledkům vzdělávání.","supporting_copy":"Partnerství může zahrnovat vývoj nebo prezentaci programu, účast expertů, vzdělávací infrastrukturu, dokumenty, registraci a ověřování. Role a odpovědnost se určují samostatně pro každý projekt.","primary_cta":"Navrhnout partnerství"},"body":"","cards":[]},{"key":"partnership_principles","title":"Partnership Principles","fields":{"h2":"Zásady partnerství"},"body":"","items":["jasné role a odpovědnost stran;","transparentní autorství a náležité představení expertů;","ověřený obsah a přesná veřejná tvrzení;","vymezené výsledky a podmínky dokončení;","samostatný model dokumentů pro každý program;","respekt k autorským právům, údajům účastníků a profesním hranicím."],"cards":[]},{"key":"partnership_models","title":"Partnership Models","fields":{"h2":"Modely partnerství"},"body":"","cards":[{"title":"Programme Partnership","fields":{"title":"Partnerství při tvorbě programů"},"body":"Pro organizace, online školy a vlastníky metodik, kteří chtějí společně strukturovat, představit nebo realizovat profesní program."},{"title":"Expert Partnership","fields":{"title":"Expertní partnerství"},"body":"Pro praktiky, lektory a autory zapojené do tvorby obsahu, výuky, hodnocení nebo odborné expertizy."},{"title":"Infrastructure Partnership","fields":{"title":"Infrastrukturní partnerství"},"body":"Pro vzdělávací projekty potřebující model dokumentů a dodatků, registraci a online ověřování výsledků."},{"title":"Distribution And Promotion Partnership","fields":{"title":"Partnerství pro distribuci a propagaci"},"body":"Pro organizace s dohodnutou rolí při prezentaci nebo distribuci konkrétních programů. Komunikace musí přesně uvádět vlastníka, poskytovatele a účastníky."}]},{"key":"academic_foundation","title":"Academic Foundation","fields":{"heading":"Exkluzivní akademické partnerství","body":"Alfred Nobel University je exkluzivním akademickým partnerem Nobel ITBS. Účast univerzity a typ univerzitního dokumentu se určují zvlášť pro každý program a automaticky se nevztahují na všechny partnerské projekty."},"body":"","cards":[{"title":"Alfred Nobel University","fields":{"location":"Dnipro, Ukrajina","partner_role":"Exkluzivní akademický partner Nobel ITBS","official_url":"https://duan.edu.ua","asset_status":"Fialové logo ve formátech SVG a PNG bylo dodáno a schváleno pro Release 1."},"body":""}]},{"key":"partner_organisations","title":"Partner Organisations","fields":{"heading":"Partnerské organizace","intro":"Představujeme organizace, jejichž role v konkrétních programech nebo projektech byla schválena ke zveřejnění."},"body":"","cards":[{"title":"Riga Nordic University","fields":{"location":"Riga, Lotyšsko","partner_role":"Partnerská organizace","official_url":"https://rnu.lv/en/","asset_status":"Z oficiálního webu bylo získáno horizontální bílé logo SVG a modrý kruhový znak PNG.","publication_status":"Aktuální partnerská karta a dodané varianty loga jsou schváleny pro Release 1."},"body":""},{"title":"Nataliia Kholodenko Psychology Centre","fields":{"partner_role":"Partnerská organizace","official_url":"https://school.kholodenko.net/","asset_status":"Oficiální čtvercový znak PNG byl získán z landing page Centra.","publication_status":"Aktuální partnerská karta a dodaný znak jsou schváleny pro Release 1."},"body":""},{"title":"e-launch Online School","fields":{"partner_role":"Partnerská organizace","official_url":"https://e-launch.net/","asset_status":"Byl dodán čtvercový soubor PNG s horizontálním logem `e-launch`.","publication_status":"Aktuální partnerská karta a dodané logo jsou schváleny pro Release 1."},"body":""},{"title":"Nobel Mental Health","fields":{"partner_role":"Partnerská organizace","official_url":"https://duan.edu.ua/pro-nas/departamenty-ta-strukturni-pidrozdily/klinika-psyhichnogo-zdorov-ja/","asset_status":"Byla dodána horizontální a čtvercová modrá loga PNG se značkou `Nobel Mental Health`.","publication_status":"Aktuální partnerské karty a dodané logo varianty jsou schváleny pro Release 1. Názvy partnerských organizací se v české verzi uvádějí v jejich schválené anglické podobě."},"body":""}]},{"key":"experts","title":"Experts","fields":{"heading":"Experti a autoři programů","intro":"Seznamte se s odborníky, kteří vytvářejí obsah, vyučují nebo poskytují profesní expertizu v konkrétních programech."},"body":"","cards":[{"title":"Nataliia Kholodenko","fields":{"public_category":"Psycholožka, kandidátka věd","expert_role":"Expertka a autorka vzdělávacích programů","asset_status":"Byla dodána portrétní fotografie ve formátu JPEG.","publication_status":"Aktuální stručný profil a fotografie jsou schváleny pro Release 1."},"body":""},{"title":"Dmytro Shevchuk","fields":{"public_category":"Praktický odborník na marketing a produkci vzdělávacích projektů","asset_status":"Byla dodána portrétní fotografie ve formátu PNG.","publication_status":"Aktuální stručný profil, fotografie a expertní role v programu AI Production jsou schváleny pro Release 1."},"body":""},{"title":"Alina Yudina","fields":{"public_category":"Psycholožka, vedoucí Nobel Mental Health, kandidátka věd","asset_status":"Byla dodána portrétní fotografie ve vysokém rozlišení ve formátu JPEG.","publication_status":"Aktuální stručný profil, fotografie a role lektorky programu General Psychology jsou schváleny pro Release 1."},"body":""}]},{"key":"partnership_boundaries","title":"Partnership Boundaries","fields":{"h2":"Hranice partnerství"},"body":"","items":["samostatné stránky partnerů a expertů nejsou součástí Release 1;","logo není důkazem akreditace ani univerzální podpory;","účast partnera se uvádí pouze u relevantního programu nebo projektu;","partneři se nikdy nezobrazují ve veřejných údajích ověřování dokumentu;","spolupráce automaticky nevytváří akademické partnerství ani právo vydávat univerzitní dokumenty."],"cards":[]},{"key":"final_cta","title":"Final CTA","fields":{"heading":"Máte program, expertizu nebo partnerský nápad?","copy":"Popište svou roli, projekt a očekávaný model spolupráce. Posoudíme, jak může odpovídat směru Nobel ITBS.","primary_cta":"Navrhnout partnerství","fallback_cta":"Napsat nám"},"body":"","cards":[]}]}'::jsonb
