        '{"blocks":[{"key":"hero","title":"Hero","fields":{"eyebrow":"B2B infrastruktura","h1":"Vzdělávací infrastruktura pro online školy a experty","lead":"Vy vytváříte obsah a vzdělávací zkušenost. My pomáháme vybudovat strukturu programu a důvěryhodný systém dokumentů.","supporting_copy":"Nobel ITBS působí jako poskytovatel a infrastrukturní partner autorských a partnerských programů. Pomáháme formalizovat program, určit model dokumentů a dodatků a zajistit registraci a online ověřování.","primary_cta":"Projednat projekt"},"body":"","cards":[]},{"key":"the_business_need","title":"The Business Need","fields":{"h2":"Obchodní potřeba"},"body":"Silný obsah nestačí bez jasných cílů, rozsahu, výsledků, podmínek dokončení a srozumitelného modelu dokumentů. Účastník, zaměstnavatel i partner musí vědět, co bylo absolvováno, v jakém rozsahu a jak dokument ověřit. Nobel ITBS propojuje tyto prvky bez zásahu do metodiky nebo autorské expertizy partnera.","cards":[]},{"key":"who_we_work_with","title":"Who We Work With","fields":{"h2":"S kým spolupracujeme"},"body":"","cards":[{"title":"Online Schools","fields":{"title":"Online školy"},"body":"Pro školy, které již vzdělávají a chtějí strukturovat programy, sjednotit dokumenty a přidat registraci a ověřování."},{"title":"Experts And Programme Authors","fields":{"title":"Experti a autoři programů"},"body":"Pro experty s metodikou, autorským kurzem nebo profesním programem, kteří potřebují jasný vzdělávací a dokumentový model."},{"title":"Educational Projects","fields":{"title":"Vzdělávací projekty"},"body":"Pro centra, komunity a iniciativy spouštějící partnerské programy a potřebující infrastrukturu výsledků vzdělávání."}]},{"key":"infrastructure_services","title":"Infrastructure Services","fields":{"h2":"Infrastrukturní služby"},"body":"","cards":[{"title":"Programme Structuring","fields":{"title":"Strukturování programu"},"body":"Popis cíle, publika, modulů, rozsahu, výsledků, hodnocení a podmínek dokončení."},{"title":"Document Model","fields":{"title":"Model dokumentů"},"body":"Název dokumentu, potvrzované údaje, struktura dodatku a vazba na výsledky."},{"title":"Document Preparation And Supplements","fields":{"title":"Příprava dokumentů a dodatků"},"body":"Struktura certifikátů, diplomů a dalších dohodnutých dokumentů a dodatků."},{"title":"Registration And Verification","fields":{"title":"Registrace a ověřování"},"body":"Registrace a ověření platného dokumentu číslem nebo QR kódem bez veřejného PDF."},{"title":"Partnership Workflow","fields":{"title":"Průběh partnerství"},"body":"Vymezení rolí autora, vlastníka programu, poskytovatele a případného akademického partnera."}]},{"key":"what_the_client_receives","title":"What The Client Receives","fields":{"h2":"Co klient získá"},"body":"Rozsah závisí na připravenosti programu, typu dokumentu a modelu spolupráce.","items":["strukturovaný popis programu;","model výsledků a hodnocení;","dohodnutý systém dokumentů a dodatků;","pravidla přípravy dat;","registraci vydaných dokumentů;","online ověření číslem nebo QR kódem;","jasné rozdělení rolí a odpovědnosti."],"cards":[]},{"key":"how_cooperation_works","title":"How Cooperation Works","fields":{"h2":"Jak spolupráce probíhá","step_1_title":"Poznáme váš projekt","step_1_body":"Posoudíme program, publikum, formát, současný model a očekávaný výsledek.","step_2_title":"Navrhneme infrastrukturu","step_2_body":"Určíme, co strukturovat, jaké dokumenty jsou vhodné a jak proběhne jejich příprava, registrace a ověření.","step_3_title":"Dohodneme model","step_3_body":"Stanovíme rozsah, role, požadavky na data a pravidla použití dokumentů.","step_4_title":"Podpoříme realizaci","step_4_body":"Pracujeme podle dohodnutého programu, infrastruktury a formátu spolupráce."},"body":"","cards":[]},{"key":"trust_and_boundaries","title":"Trust And Boundaries","fields":{"h2":"Důvěra a hranice"},"body":"Nobel ITBS působí prostřednictvím české společnosti Nobel ITBS s.r.o. a má exkluzivní akademické partnerství s Univerzitou Alfreda Nobela. Účast univerzity, typ dokumentu a možnost vydání se určují zvlášť pro každý program. Kontakt nezaručuje schválení, univerzitní dokument, ECTS ani určitý status.","cards":[]},{"key":"faq","title":"FAQ","fields":{"h2":"Časté dotazy"},"body":"","cards":[{"title":"Musí být program hotový?","fields":{},"body":"Ne. Lze přijít s hotovým programem, metodikou i strukturou k dopracování."},{"title":"Musím převést autorská práva?","fields":{},"body":"Model práv se sjednává samostatně; infrastrukturní spolupráce automatický převod neznamená."},{"title":"Může každý program získat univerzitní certifikát?","fields":{},"body":"Ne. Záleží na obsahu, rozsahu, výsledcích, hodnocení a dohodnutém modelu."},{"title":"Lze využít jen registraci a ověřování?","fields":{},"body":"Rozsah služeb se určí po posouzení programu a stávajícího systému dokumentů."}]},{"key":"final_cta","title":"Final CTA","fields":{"heading":"Vybudujme infrastrukturu pro váš vzdělávací program","copy":"Popište projekt, současný formát a plánované dokumenty. Po úvodním posouzení navrhneme další krok.","primary_cta":"Projednat projekt","fallback_cta":"Napsat nám"},"body":"","cards":[]}]}'::jsonb
      )
  )
  update public.content_page_translations as translation
  set sections = replacements.sections
  from public.content_pages as page,
    replacements
  where page.id = translation.page_id
    and page.page_key = replacements.page_key
    and translation.language_code = replacements.language_code;

  get diagnostics affected_rows = row_count;
  if affected_rows <> 9 then
    raise exception
      'QA-SEMANTIC-001 expected 9 managed-page translations, updated %',
      affected_rows;
  end if;
end
$$;

